#pragma once

#include "Sm64.h"

// Mario on screen: meshes/TES64/mario.nif (a template of 3072 placeholder vertices, generated by
// tools/make_mario_nif.py) whose GPU vertex buffers are rewritten every tick from libsm64's geometry. Skyrim draws,
// lights and shadows it like any other mesh.
namespace Render
{
	// writes Data/Textures/TES64/mario.dds from the ROM's texture atlas (before the mesh loads)
	bool WriteAtlas();

	bool Show();   // load (once) and put Mario in the world
	void Hide();

	// a_toSkyrim maps an SM64 position to Skyrim space; a_root is where the node sits (Mario's position)
	// a_flags: libsm64's Mario flags (Metal/Vanish caps change how he's drawn)
	void Update(const SM64MarioGeometryBuffers& a_geo, const RE::NiPoint3& a_root, const std::function<RE::NiPoint3(const float*)>& a_toSkyrim, std::uint32_t a_flags);

	bool Visible();
	RE::NiAVObject* Root();   // Mario's node (under the player's root)
	std::uint32_t TrianglesDrawn();
}
